### Type mocked modules using jest.Mocked

Source: https://github.com/jestjs/jest/blob/main/docs/MockFunctionAPI.md

Wrap source definitions with mock function types using the jest.Mocked utility type for mocked modules.

```ts
import {expect, jest, test} from '@jest/globals';
import type {fetch} from 'node-fetch';

jest.mock('node-fetch');

let mockedFetch: jest.Mocked<typeof fetch>;

afterEach(() => {
  mockedFetch.mockClear();
});

test('makes correct call', () => {
  mockedFetch = getMockedFetch();
  // ...
});

test('returns correct data', () => {
  mockedFetch = getMockedFetch();
  // ...
});
```

